data_contract.model:
id; number uint; year smallint (non fillable, D-11); unique(company_id, year, number);
supplier_id FK registries restrict req; company_id FK companies req; company_site_id FK req;
operational_site_id FK null; order_date date req; description string(255) req;
general_notes text null; payment_method_id FK null; is_internal_user bool default false;
customer_id FK registries null; work_order_id FK null; quote_id FK null; opportunity_id FK null;
sector_notes string(500) null; status enum default draft (indice);
taxable_total, vat_total, grand_total decimal(14,2) default 0 (non fillable);
copy_group_id uuid null (indice); created_by FK users (non fillable); timestamps.
Indici: supplier_id, order_date, status.

id; purchase_order_id FK cascade; position uint; product_id FK null; description string(500) req;
cost_type_id FK cost_types restrict req; unit_of_measure_id FK null; quantity decimal(12,3);
unit_price decimal(14,2); vat_rate_id FK null; taxable_amount, vat_amount, total_amount
decimal(14,2) (non fillable); work_order_id FK null;
purchase_request_line_id FK purchase_request_lines null, UNIQUE, nullOnDelete (non fillable:
scritto solo da D-17); timestamps.

id; destination_purchase_order_id FK cascade; source_purchase_order_id FK null nullOnDelete;
source_code string(20); source_snapshot json; moved_line_ids json; source_action enum
deleted|partial; performed_by FK users; created_at.
